mapper.select:
SELECT info.id, info.title, info.content, info.publish_time, info.type_id, info.cover, info.summary, info.business_id, mu.id AS userMsgId, mu.read_status, mn.type as typeLabel FROM sys_message_info info LEFT JOIN sys_message_user mu ON mu.msg_id = info.id LEFT JOIN sys_message_notice mn ON mn.msg_id = info.id
AND info.`status` = 1 AND info.publish_time <= NOW()
AND mn.type IN
#{item}
AND mu.read_status = #{condition.readStatus}
AND mu.user_id = #{condition.userId}
AND info.title like concat('%',#{condition.title}, '%')
AND info.tenant_id = #{condition.tenantId}
AND info.publish_time BETWEEN #{condition.startTime} AND #{condition.endTime}
ORDER BY info.publish_time DESC

SELECT
me.*,
us.nick_name,
info.title,
info.summary,
info.remark,
info.link_url,
info.content,
info.publish_time,
se.nick_name as publisherName
FROM
sys_message_user me
left join uic_user_info us
on me.user_id = us.id
left join sys_message_info info
on me.msg_id = info.id
left join uic_user_info se
on info.publisher = se.id


        AND me.id = #{condition.id}


        AND info.title like concat('%',#{condition.title}, '%')


        AND info.type_id = #{condition.typeId}


        AND me.user_id = #{condition.userId}


        AND me.msg_id = #{condition.msgId}


        AND me.read_status = #{condition.readStatus}


        AND me.confirm_status = #{condition.confirmStatus}


        AND me.like_status = #{condition.likeStatus}


        AND me.collect_status = #{condition.collectStatus}


        AND me.link_param = #{condition.linkParam}


        AND me.reply_content = #{condition.replyContent}


        AND me.status = #{condition.status}


        AND me.status != 1


        AND me.status = 0


        AND me.create_time = #{condition.createTime}


        AND me.creator_id = #{condition.creatorId}


        AND me.update_time = #{condition.updateTime}


        AND me.updator_id = #{condition.updatorId}


           and DATE_FORMAT(info.create_time, '%Y-%m-%d %H:%i:%s')>=  DATE_FORMAT(#{condition.startTime}, '%Y-%m-%d %H:%i:%s')   


           and DATE_FORMAT(info.create_time, '%Y-%m-%d %H:%i:%s')<=  DATE_FORMAT(#{condition.endTime}, '%Y-%m-%d %H:%i:%s')   


ORDER BY info.publish_time DESC

SELECT
me.*,
us.nick_name,
info.title,
info.summary,
info.remark,
info.content,
info.link_url,
info.publish_time,
se.nick_name as publisherName,
ty.name as typeName
FROM
sys_message_user me
left join uic_user_info us
on me.user_id = us.id
left join sys_message_info info
on me.msg_id = info.id
left join uic_user_info se
on info.publisher = se.id


        AND me.id = #{condition.id}


        AND info.title like concat('%',#{condition.title}, '%')


        AND info.type_id = #{condition.typeId}


        AND me.user_id = #{condition.userId}


        AND me.msg_id = #{condition.msgId}


        AND me.read_status = #{condition.readStatus}


        AND me.confirm_status = #{condition.confirmStatus}


        AND me.like_status = #{condition.likeStatus}


        AND me.collect_status = #{condition.collectStatus}


        AND me.link_param = #{condition.linkParam}


        AND me.reply_content = #{condition.replyContent}


        AND me.status = #{condition.status}


        AND me.status != 1


        AND me.status = 0


        AND me.create_time = #{condition.createTime}


        AND me.creator_id = #{condition.creatorId}


        AND me.update_time = #{condition.updateTime}


        AND me.updator_id = #{condition.updatorId}


           and DATE_FORMAT(info.create_time, '%Y-%m-%d %H:%i:%s')>=  DATE_FORMAT(#{condition.startTime}, '%Y-%m-%d %H:%i:%s')   


           and DATE_FORMAT(info.create_time, '%Y-%m-%d %H:%i:%s')<=  DATE_FORMAT(#{condition.endTime}, '%Y-%m-%d %H:%i:%s')   


ORDER BY info.publish_time DESC
